    article.answers.forEach((_, index) => { const id = index + 1; passageHtml = passageHtml.replace(`{${id}}`, `<span class="blank-wrap"><button class="blank" data-blank="${id}">空缺 ${id}</button><button class="later-btn" data-later="${id}" title="暂缓">!</button></span>`); });
